variables.announcement:
{%- set attrs = states.binary_sensor.balcony_h2c_hms_errors.attributes | default({}, true) -%}
{%- set ns = namespace(parts=[]) -%}
{%- for prefix in attrs.keys() | select('search', '-Code$') | map('regex_replace', '-Code$', '') | list -%}
  {%- if attrs[prefix ~ '-Code'] not in error_blacklist -%}
    {%- set ns.parts = ns.parts + [attrs[prefix ~ '-Error']] -%}
  {%- endif -%}
{%- endfor -%}
{%- set hms = ns.parts | join(' ') -%}
{%- set print_code = state_attr('binary_sensor.balcony_h2c_print_error', 'code') -%}
{%- set print_err = state_attr('binary_sensor.balcony_h2c_print_error', 'error') -%}
{%- set print_err = print_err if print_code not in error_blacklist else none -%}
{%- set details = hms or print_err -%}
{{ 'Printer error. ' ~ details if details else '' }}

variables.media_kind:
{%- set title = raw_title | string -%}
{%- set first = (title.split(' ', 1)[0] if title else '') | lower -%}
{%- if raw_type in ['movie', 'film'] -%} movie
{%- elif raw_type in ['show', 'series', 'tv', 'tv show', 'tv series'] -%} show
{%- elif first in ['movie', 'film'] -%} movie
{%- elif first in ['show', 'series', 'tv', 'television'] -%} show
{%- else -%} unknown
{%- endif -%}

variables.clean_title:
{%- if raw_type == '' and media_kind in ['movie', 'show'] -%}
{{ raw_title | string | regex_replace('^(movie|film|tv show|tv series|television show|television series|show|series|tv) +', '', ignorecase=True) }}
{%- else -%}{{ raw_title | string }}{%- endif -%}

variables.media_kind:
{% set kind = (llm_kind.response.speech.plain.speech or '').lower() %} {{ 'movie' if kind == 'movie'
   else 'show' if kind == 'show'
   else 'unknown' }}

default.set_conversation_response:
{% if witty_remark is defined and witty_remark.data %}
  {{ witty_remark.data }}
{% else %}
  Got it — "{{ clean_title }}" has been added to your {{ media_kind }} queue.
{% endif %}

variables.message:
{% set ns = namespace(t='') %} {# current #} {% set ns.t = ns.t ~ "It's " ~ (now_temp | round(0)) ~ " degrees and " ~ now_cond ~ ". " %} {% if diff > 2 %}
  {% set ns.t = ns.t ~ "Feels like " ~ (now_feels | round(0)) ~ " degrees. " %}
{% endif %} {% if now_precip > 0 %}
  {% set ns.t = ns.t ~ "There's precipitation right now. " %}
{% endif %} {# next 6 h #} {% if will_rain %}
  {% set ns.t = ns.t ~ "Rain is likely within the next few hours. " %}
{% endif %} {% if (max_t - now_temp) > 3 %}
  {% set ns.t = ns.t ~ "It will warm up to about " ~ (max_t | round(0)) ~ " degrees in the next six hours. " %}
{% elif (now_temp - min_t) > 3 %}
  {% set ns.t = ns.t ~ "Expect it to cool down to around " ~ (min_t | round(0)) ~ " degrees in the next six hours. " %}
{% endif %} {{ ns.t | trim }}

variables.end:
{% if start != 'NA' %}
{% set start = as_datetime(start) %}
{% set add = time_period_length | default(1) | int(1) %}
{% set type = time_period_type | default if time_period_type | default in ['daily', 'hourly'] else 'daily' %}
{{ (start + timedelta(days = add if type == 'daily' else 0, hours = add if type == 'hourly' else 0)).isoformat() }}
{% endif %}

selected_data.forecast:
{% set ns = namespace(forecast=[]) %}
{% for item in weather_response[weather_entity].forecast %}
{% if start | as_datetime <= item.datetime | as_datetime | as_local < end | as_datetime %}
{% set ns.forecast = ns.forecast + [item] %}
{% endif %}
{% endfor %} {{ ns.forecast }}

averaged.averaged_weather_data_for_period:
{% set ns = namespace(combined={}) %}
{% set weather_data = selected_data.forecast %}
{% set forecast_keys = (weather_data[0] | default({})).keys() | reject('eq', 'datetime') %}
{% for item in forecast_keys %}
{% set combine = weather_data | map(attribute=item) | list %}
{% set combine = combine | statistical_mode if combine[0] is string else combine | average | round %}
{% set ns.combined = dict(ns.combined, **{item: combine}) %}
{% endfor %}
{{ dict(start_of_period=start, end_of_period=end, **ns.combined) }}
